service.method:

UPDATE SDCGL
   SET DEL_FLAG = 'Y'
      ,CHANGE_DATE    = ${current.DATE}
      ,CHANGE_TIME    = ${current.TIME}
      ,CHANGE_USER_ID = ${session.ID}
 WHERE 1=1
   AND DOC_TYPE       = ${DOC_TYPE}


UPDATE SDCLN
   SET DEL_FLAG       = 'Y'
      ,CHANGE_DATE    = ${current.DATE}
      ,CHANGE_TIME    = ${current.TIME}
      ,CHANGE_USER_ID = ${session.ID}
 WHERE 1=1
   AND DOC_TYPE  = ${DOC_TYPE}
   AND SEQ       = ${SEQ}


			INSERT 
			  INTO SDCLN (
			       DOC_TYPE
			      ,SEQ
			      ,COMPANY_CODE
			      ,PLANT_CODE
			      ,ADD_DATE
			      ,ADD_USER_ID
			      ,CHANGE_DATE
			      ,CHANGE_USER_ID
			      ,PREFIX_FORMAT
			      ,START_NO
			      ,END_NO
			      ,CURRENT_NO
			      ,MANUAL_FLAG
			      ,USE_FLAG
			      ,YEAR_FLAG
			      ,MONTH_FLAG
			      ,DAY_FLAG
			      ,ADD_TIME
			      ,CHANGE_TIME
			      ,DEL_FLAG
		  )VALUES(
        		  ${DOC_TYPE}
         		 ,${SEQ}
        		 ,${session.COMPANY_CODE}
        		 ,${session.PLANT_CODE}
        		 ,${current.date}
        		 ,${session.ID}
        		 ,${current.date}
        		 ,${session.ID}
        		 ,${PREFIX_FORMAT}
        		 ,${START_NO}
        		 ,${END_NO}
        		 ,${CURRENT_NO}
        		 ,(CASE ${MANUAL_FLAG} WHEN '자동' THEN '1' WHEN '수동' THEN '0' ELSE '0' END)
			     ,(CASE ${USE_FLAG}		WHEN '1' THEN 'Y' ELSE '0' END)
			     ,(CASE ${YEAR_FLAG}	WHEN '1' THEN 'Y' ELSE '0' END)
			     ,(CASE ${MONTH_FLAG}	WHEN '1' THEN 'Y' ELSE '0' END)
			     ,(CASE ${DAY_FLAG}		WHEN '1' THEN 'Y' ELSE '0' END)
        		 ,${current.time}
        		 ,${current.time}
        		 ,'N'
	        )


UPDATE  SDCLN
   SET  PREFIX_FORMAT   = ${PREFIX_FORMAT}
       ,START_NO        = ${START_NO}
       ,END_NO          = ${END_NO}
       ,YEAR_FLAG       = (CASE ${YEAR_FLAG}	WHEN '1' THEN 'Y' ELSE '0' END)
       ,MONTH_FLAG      = (CASE ${MONTH_FLAG}	WHEN '1' THEN 'Y' ELSE '0' END)
       ,DAY_FLAG        = (CASE ${DAY_FLAG}		WHEN '1' THEN 'Y' ELSE '0' END)
       ,CURRENT_NO      = ${CURRENT_NO}
       ,MANUAL_FLAG     = CASE
					           WHEN MANUAL_FLAG = '자동' THEN '1'
					           WHEN MANUAL_FLAG = '수동' THEN '0'
					           ELSE '2'
					       END
       ,USE_FLAG        = (CASE ${USE_FLAG}		WHEN '1' THEN 'Y' ELSE '0' END)
       ,CHANGE_DATE     = ${current.DATE}
       ,CHANGE_TIME     = ${current.TIME}
       ,CHANGE_USER_ID  = ${session.ID}   
 WHERE DOC_TYPE = ${DOC_TYPE}
   AND SEQ      = ${SEQ}


			UPDATE  SDCGL
			   SET  COMPANY_CODE   = ${session.COMPANY_CODE}
			       ,PLANT_CODE     = ${session.PLANT_CODE}
             	   ,CHANGE_DATE    = ${current.DATE}
             	   ,CHANGE_USER_ID = ${current.ID}
             	   ,DESCRIPTION    = ${DESCRIPTION}
             	   ,CHANGE_TIME    = ${current.TIME}
             	   ,HOUSE_CODE     = ${session.HOUSE_CODE}
			 WHERE DOC_TYPE        = ${DOC_TYPE}


SELECT nvl(MAX(SEQ),'0')   AS MAXSEQ
  FROM SDCLN
 WHERE DOC_TYPE = ${DOC_TYPE}


SELECT COUNT(SEQ) 
FROM SDCLN
 WHERE DOC_TYPE = ${DOC_TYPE}
   AND SEQ      = ${SEQ}
